const canvas = document.querySelector('#game-canvas');
const ctx = canvas.getContext('2d');
const $ = (s) => document.querySelector(s);
const TILE = 48, ZW = 1200, ZH = 900;
const zones = [
  ['Meadow Start','meadow','#59874a','A grassy home clearing with calm beginner Pokémon.'],
  ['Deepwood','forest','#345c3d','Old trees, hidden paths, and rare woodland Pokémon.'],
  ['Sunset Dunes','desert','#b4884d','Warm sand and fire Pokémon move through the dunes.'],
  ['Tidepool Coast','water','#327991','Water Pokémon gather along the shore.'],
  ['Mossfen','swamp','#486e56','A misty wetland full of unusual species.'],
  ['Stone Cave','rock','#565a60','Rock Pokémon hide between the cave pillars.'],
  ['Red Badlands','ground','#966c4c','Dry canyons are home to ground Pokémon.'],
  ['Cloudpeak','mountain','#60798c','Cold winds bring flying and ice Pokémon.'],
  ['Ember Caldera','fire','#754d49','Volcanic paths glow under the ash clouds.'],
  ['Snowfield','ice','#7295a0','A bright tundra where ice Pokémon roam.'],
  ['Wind Isles','flying','#557c9a','Floating trails and wide skies attract flying Pokémon.'],
  ['Crystal Garden','fairy','#786589','Crystal blooms shelter rare fairy Pokémon.'],
  ['Ancient Grove','grass','#395944','A primeval forest with uncommon grass Pokémon.'],
  ['Abyssal Bay','water','#295b78','Deep water species swim beneath the cliffs.'],
  ['Dragon Valley','dragon','#714d59','Powerful dragon Pokémon guard the far valley.'],
  ['Legend Shrine','psychic','#5d527f','A quiet endgame sanctuary with very rare Pokémon.'],
];
const typeEmoji = {normal:'💥',fire:'🔥',water:'💧',electric:'⚡',grass:'🍃',ice:'❄️',fighting:'👊',poison:'☠️',ground:'🪨',flying:'🌪️',psychic:'🔮',bug:'🐛',rock:'🪨',ghost:'👻',dragon:'🐉',dark:'🌑',steel:'⚙️',fairy:'✨'};
const colors={grass:'#72d48a',water:'#56c9ef',fire:'#ff815c',electric:'#ffe66b',ground:'#d6b076',rock:'#c4ae8a',ice:'#bcefff',flying:'#b2c9ff',psychic:'#e69bd7',dragon:'#9e91ff',fairy:'#ffb4dc',normal:'#e0d8b5',dark:'#aaa0b4',ghost:'#aa90ee',poison:'#b88cde',bug:'#c3dc6c',steel:'#b9c8cc',fighting:'#ff9a78'};
const lowStarters=[1,4,7,25,37,54,58,60,66,69,77,90,102,133,152,155,158,172,175,252,255,258,280,387,390,393,495,498,501,511,513,515,650,653,656,722,725,728,810,813,816,906,909,912,1001];
const dailyQuestPool=[{kind:'catch',name:'Catch a wild Pokémon',target:1,reward:35},{kind:'battle',name:'Win a Pokémon battle',target:1,reward:40},{kind:'travel',name:'Explore two new biomes',target:2,reward:45},{kind:'harvest',name:'Harvest two garden crops',target:2,reward:30}];
let species=[];
try { species=await fetch('/data/pokedex.json').then(r=>{if(!r.ok)throw Error('Pokédex data unavailable');return r.json();}); } catch(error) { console.error(error); }
const byId=new Map(species.map(p=>[p.id,p]));
const sprites=new Map(), cries=new Map(),sounds=new Map();let currentMusic=null,currentTrack='';
const state={user:null,mode:'game',profile:null,saveTimer:0,toastTimer:0,frame:0,keys:new Set(),lastTime:0,dirty:false,
  player:{x:600,y:440,hp:100,maxHp:100,gender:'female',style:0,level:1,xp:0,full:85,thirst:85,energy:90,mood:80,money:150,day:1,hour:8},
  zone:0,team:[],active:0,activeTeam:[],party:[],seen:new Set(),caught:new Set(),bag:{'Poké Ball':5,'Berry':2,'Potion':1,'Seed':2},farm:[null,null,null,null],wild:[],encounter:null,battle:null,overlay:null,quest:{name:'Meet a Pokémon',kind:'catch',done:0,target:1,reward:25,claimed:false},
  online:{url:window.OPENRPG_CONFIG?.onlineServerUrl||localStorage.getItem('openrpg-online-url')||'',code:'',token:localStorage.getItem('openrpg-online-token')||'',client:null,connecting:false,state:null,poll:0,inputBusy:false,keys:{},invite:null,seenOffers:new Set(),lastEventSeq:0,chat:'',lastSend:0}};

const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showToast(text){const el=$('#world-toast');el.textContent=text;el.classList.remove('hidden');state.toastTimer=2.5;}
function api(path,options={}){return fetch(path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})}}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d;});}
function requestSave(){if(!state.user||!state.profile)return;state.dirty=true;$('#save-label').textContent='SAVING';$('.save-status').classList.add('saving');}
function serialize(){return {version:1,profile:state.profile,player:state.player,zone:state.zone,team:state.team,active:state.active,activeTeam:state.activeTeam,party:state.party,seen:[...state.seen],caught:[...state.caught],bag:state.bag,farm:state.farm,quest:state.quest};}
async function saveNow(){if(!state.user||!state.profile||!state.dirty)return;state.dirty=false;try{await api('/api/save',{method:'PUT',body:JSON.stringify({gameState:serialize()})});$('#save-label').textContent='SAVED';$('.save-status').classList.remove('saving');}catch(e){state.dirty=true;$('#save-label').textContent='OFFLINE';console.error(e);}}
function loadSave(saved){if(!saved?.profile)return false;const p=saved.player||{};Object.assign(state.player,p);state.profile=saved.profile;state.zone=Math.max(0,Math.min(15,saved.zone||0));state.party=saved.party||[];state.team=saved.team||state.party.map(x=>x.id);state.active=saved.active||0;state.activeTeam=(saved.activeTeam||state.team.slice(0,3)).slice(0,3);state.seen=new Set(saved.seen||[]);state.caught=new Set(saved.caught||[]);state.bag={...state.bag,...saved.bag};state.farm=saved.farm||state.farm;state.quest=saved.quest||state.quest;return true;}
function activePokemon(slot=state.active){return state.party.find(p=>p.id===state.activeTeam[slot])||state.party[0]||makePokemon(state.team[0]||1,5);}
function activatePokemon(id){if(!state.team.includes(id))return;let slot=state.activeTeam.indexOf(id);if(slot<0){slot=state.activeTeam.length<3?state.activeTeam.length:state.active;state.activeTeam[slot]=id;}state.active=slot;renderParty();requestSave();showToast(`${getDetail(id).name} is active.`);}
function makeDailyQuest(){const q=dailyQuestPool[Math.floor(Math.random()*dailyQuestPool.length)];return {...q,done:0,claimed:false,day:state.player.day};}
function questProgress(kind,amount=1){const q=state.quest;if(q.kind===kind&&!q.claimed)q.done=Math.min(q.target,(q.done||0)+amount);updateHud();requestSave();}
function claimQuest(){const q=state.quest;if(!q||q.claimed||q.done<q.target)return;state.player.money+=q.reward;const bonus=Math.random()<.35?'Poké Ball':'Berry';state.bag[bonus]=(state.bag[bonus]||0)+1;q.claimed=true;showToast(`Daily reward: ${q.reward} coins + 1 ${bonus}.`);updateHud();requestSave();}
function randomStarter(){const id=lowStarters[Math.floor(Math.random()*lowStarters.length)];return makePokemon(id,5);}
function makePokemon(id,level=5){const p=byId.get(Number(id));if(!p)return {id:Number(id),level,hp:40,maxHp:40,xp:0};const hp=32+Math.round((p.stats.hp||45)*.55)+level*2;return {id:p.id,level,hp,maxHp:hp,xp:0};}
function applyUser(user){state.user=user;$('#auth-view').classList.add('hidden');$('#game-view').classList.remove('hidden');$('#trainer-label').textContent=user.username.toUpperCase();if(!loadSave(user.gameState)){openSetup();}else{populateZone(true);renderParty();setZoneMusic();showToast('Welcome back, '+user.username+'!');}requestAnimationFrame(loop);}
function setTab(tab){const login=tab==='login';$('#tab-login').classList.toggle('active',login);$('#tab-register').classList.toggle('active',!login);$('#tab-login').setAttribute('aria-selected',String(login));$('#tab-register').setAttribute('aria-selected',String(!login));$('#password').autocomplete=login?'current-password':'new-password';$('#auth-submit').innerHTML=login?'Log in <span aria-hidden="true">↗</span>':'Create account <span aria-hidden="true">↗</span>';$('#auth-hint').textContent=login?'Use the username and password for your OpenRPG account.':'Your username becomes your trainer name. You can add social sign-in later.';$('#auth-error').textContent='';$('#auth-form').dataset.action=tab;}
$('#tab-register').addEventListener('click',()=>setTab('register'));$('#tab-login').addEventListener('click',()=>setTab('login'));
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('#auth-submit');btn.disabled=true;$('#auth-error').textContent='';try{const action=$('#auth-form').dataset.action||'register';const data=await api(`/api/auth/${action}`,{method:'POST',body:JSON.stringify({username:$('#username').value.trim(),password:$('#password').value})});const me=await api('/api/auth/me');applyUser(me.user);$('#password').value='';}catch(error){$('#auth-error').textContent=error.message;}finally{btn.disabled=false;}});
$('#logout-btn').addEventListener('click',async()=>{saveNow();disconnectOnline();await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.user=null;state.profile=null;state.mode='game';$('#game-view').classList.add('hidden');$('#auth-view').classList.remove('hidden');});

function openSetup(){state.mode='setup';drawOverlay(`<section class="overlay-card"><h2>NEW ADVENTURE</h2><p>Choose your look and meet your first Pokémon. Your starter is selected at random.</p><label class="setup-label">Trainer style</label><div class="setup-options"><button data-gender="female" class="choice selected">♀ Explorer</button><button data-gender="male" class="choice">♂ Adventurer</button></div><p class="starter-preview">✦ A young Pokémon will join your team at level 5.</p><button id="start-adventure" class="primary-btn">START ADVENTURE <span>↗</span></button></section>`);
  document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-gender]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.player.gender=b.dataset.gender;});
  $('#start-adventure').onclick=()=>{const starter=randomStarter();state.team=[starter.id];state.party=[starter];state.activeTeam=[starter.id];state.active=0;state.farm=[null,null,null,null];state.quest=makeDailyQuest();state.caught.add(starter.id);state.seen.add(starter.id);state.player.gender=document.querySelector('[data-gender].selected').dataset.gender;state.player.x=600;state.player.y=440;state.zone=0;state.profile={createdAt:new Date().toISOString()};state.mode='game';closeOverlay();populateZone(true);renderParty();setZoneMusic();requestSave();showToast(`${byId.get(starter.id)?.name||'Pokémon'} joined your team!`);};
}
function drawOverlay(html){const root=$('#overlay');root.innerHTML=html;root.classList.remove('hidden');state.overlay=true;}
function closeOverlay(){const root=$('#overlay');root.classList.add('hidden');root.innerHTML='';state.overlay=null;if(state.mode!=='battle'&&state.mode!=='battleIntro')state.mode='game';canvas.focus?.();}

function sprite(id){id=Number(id);if(!sprites.has(id)){const im=new Image();im.decoding='async';im.src=`/assets/pokemon-sprites/${id}.png`;im.onerror=()=>{im.src=`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`;};sprites.set(id,im);}return sprites.get(id);}
function playSound(file,volume=.5){let audio=sounds.get(file);if(!audio){audio=new Audio(`/assets/audio/${file}`);audio.preload='none';sounds.set(file,audio);}audio.pause();audio.currentTime=0;audio.volume=volume;audio.play().catch(()=>{});}
function setMusic(file){if(currentTrack===file)return;if(currentMusic)currentMusic.pause();currentTrack=file;if(!currentMusic){currentMusic=new Audio();currentMusic.loop=true;currentMusic.volume=.24;}currentMusic.src=`/assets/audio/${file}`;currentMusic.load();currentMusic.play().catch(()=>{});}
function setZoneMusic(){const tracks=['music/meadow.ogg','music/forest.ogg','music/desert.ogg','music/ocean.ogg','music/swamp.ogg','music/cavern.ogg','music/ruins.ogg','music/sky.ogg','music/desert.ogg','music/snow.ogg','music/sky.ogg','music/fairy.ogg','music/forest.ogg','music/ocean.ogg','music/mystical.ogg','music/mystical.ogg'];setMusic(tracks[state.zone]||tracks[0]);}
function typeSfx(type){const file={fire:'fire.ogg',water:'water.ogg',grass:'leaf.ogg',ground:'earth.ogg',rock:'earth.ogg',flying:'wind.ogg',normal:'punch.ogg',fighting:'punch.ogg'}[type]||'wind.ogg';return `sfx/${file}`;}
function playCry(id){let a=cries.get(id);if(!a){a=new Audio(`https://raw.githubusercontent.com/PokeAPI/cries/main/cries/pokemon/latest/${id}.ogg`);a.volume=.55;cries.set(id,a);}a.currentTime=0;a.play().catch(()=>{});}
function rangeIdForZone(index){const [name,biome]=zones[index];const types=({meadow:['normal','grass','bug'],forest:['grass','bug','poison','normal'],desert:['fire','ground','rock'],water:['water','ice'],swamp:['water','poison','grass','bug'],rock:['rock','ground','steel'],ground:['ground','rock','fire'],mountain:['rock','flying','ice'],fire:['fire','rock','dragon'],ice:['ice','water'],flying:['flying','electric'],fairy:['fairy','psychic','grass'],ancient:['grass','bug','dragon'],deepsea:['water','dark','ice'],dragon:['dragon','fire','flying'],psychic:['psychic','ghost','fairy']})[biome]||['normal'];
 const maxId=index<4?151:index<8?386:index<12?649:index<15?905:1025;let pool=species.filter(p=>p.id<=maxId&&p.types.some(t=>types.includes(t)));if(index===0)pool=pool.filter(p=>p.id<152);if(index>=12)pool=pool.filter(p=>p.id>250);if(!pool.length)pool=species.slice(0,151);return pool;}
function populateZone(reset=false){if(reset||!state.wild.length){const pool=rangeIdForZone(state.zone),count=3+Math.floor(Math.random()*3);state.wild=[];for(let i=0;i<count;i++){let p=pool[Math.floor(Math.random()*pool.length)];if(state.zone>=12&&Math.random()<.20)p=species.filter(x=>x.id>700)[Math.floor(Math.random()*Math.min(300,species.filter(x=>x.id>700).length))]||p;state.wild.push({id:p.id,x:100+Math.random()*1000,y:150+Math.random()*650,vx:(Math.random()-.5)*38,vy:(Math.random()-.5)*25,timer:1+Math.random()*4,state:'roam',level:Math.max(2,Math.min(60,3+state.zone*3+Math.floor(Math.random()*4))),rare:state.zone>3&&Math.random()<.1});}}}
function nearestPokemon(radius=80){return state.wild.filter(p=>p.state!=='hide').map(p=>[Math.hypot(p.x-state.player.x,p.y-state.player.y),p]).filter(x=>x[0]<radius).sort((a,b)=>a[0]-b[0])[0]?.[1]||null;}
function getDetail(id){return byId.get(Number(id))||{id,name:'Unknown Pokémon',types:['normal'],stats:{hp:45,attack:50,defense:45,'special-attack':50,speed:45},moves:[]};}
function worldMinutes(){return (state.player.day-1)*1440+Math.floor(state.player.hour*60);}
function advanceClock(hours){const total=state.player.hour+hours;state.player.day+=Math.floor(total/24);state.player.hour=total%24;if(state.quest.day!==state.player.day)state.quest=makeDailyQuest();}
function gardenAction(){const index=Math.max(0,Math.min(3,Math.floor((state.player.x-105)/35))),crop=state.farm[index];if(!crop){if((state.bag.Seed||0)<1)return showToast('The garden needs seeds.');state.bag.Seed--;state.farm[index]={readyAt:worldMinutes()+180};playSound('sfx/actions/seed-plant.wav');showToast('Seed planted. It will be ready after three in-game hours.');}else if(worldMinutes()>=crop.readyAt){state.farm[index]=null;state.bag.Produce=(state.bag.Produce||0)+1;playSound('sfx/actions/harvest-pop.wav');questProgress('harvest');showToast('Harvested one crop. Sell it at the market.');}else showToast('This crop is still growing. Rest or advance the in-game time.');requestSave();}
function interact(){if(state.mode!=='game')return;const nearby=nearestPokemon(95);if(nearby){state.encounter=nearby;state.seen.add(nearby.id);playCry(nearby.id);playSound('sfx/actions/bush-rustle.wav',.4);openEncounter();requestSave();return;}if(state.zone===0&&state.player.x>=90&&state.player.x<=260&&state.player.y>=620&&state.player.y<=735){gardenAction();return;}if(state.zone===0&&state.player.x<240&&state.player.y<250){advanceClock(8);state.player.hp=state.player.maxHp;state.player.energy=100;state.player.full=100;state.player.thirst=100;state.player.mood=Math.min(100,state.player.mood+15);state.party.forEach(p=>p.hp=p.maxHp);renderParty();playSound('sfx/actions/sleep.wav');showToast('Rested at home. Needs and Pokémon are restored.');requestSave();return;}if(state.player.x>930&&state.player.y<235){openShop();return;}if(state.player.x>920&&state.player.y>670){const cost=5;if(state.player.money<cost)return showToast('Center service costs 5 coins.');state.player.money-=cost;state.party.forEach(p=>p.hp=p.maxHp);state.player.energy=100;state.player.full=100;state.player.thirst=100;renderParty();questProgress('center');playSound('sfx/actions/notification.wav');showToast('Pokémon Center service complete · 5 coins.');requestSave();return;}const gate=nearGate();if(gate){const next=gate.index;state.zone=next;state.player.x=gate.from==='left'?ZW-70:gate.from==='right'?70:state.player.x;state.player.y=gate.from==='top'?ZH-70:gate.from==='bottom'?70:state.player.y;populateZone(true);setZoneMusic();playSound('sfx/actions/gate.wav');questProgress('travel');updateHud();requestSave();showToast(`Entered ${zones[next][0]}.`);return;}showToast('Nothing close by. Walk up to a Pokémon, shop, center, garden, or trail.');}
function openEncounter(){const p=getDetail(state.encounter.id),spriteUrl=`/assets/pokemon-sprites/${p.id}.png`;state.mode='encounter';drawOverlay(`<section class="overlay-card encounter-card"><button class="overlay-close" id="close-overlay" aria-label="Close">×</button><h2>WILD POKÉMON</h2><div class="encounter-head"><img src="${spriteUrl}" alt="${escapeHtml(p.name)}"><div><h3>${escapeHtml(p.name)}</h3><p>${p.types.map(t=>`<span class="type-chip">${t.toUpperCase()}</span>`).join(' ')} · Lv.${state.encounter.level}</p><p>HP ${calcHp(state.encounter.id,state.encounter.level)}</p><button id="cry-btn" class="small-btn">▶ Play cry</button></div></div><p>What would you like to do?</p><div class="encounter-buttons"><button id="info-btn" class="menu-btn">Pokédex information</button><button id="fight-btn" class="menu-btn highlighted">Challenge to battle</button></div></section>`);$('#close-overlay').onclick=closeOverlay;$('#cry-btn').onclick=()=>playCry(p.id);$('#info-btn').onclick=()=>openPokemonInfo(p.id);$('#fight-btn').onclick=()=>startWildBattle();}
function openPokemonInfo(id){const p=getDetail(id);drawOverlay(`<section class="overlay-card"><button class="overlay-close" id="close-overlay">×</button><h2>POKÉDEX ENTRY</h2><div class="encounter-head"><img src="/assets/pokemon-sprites/${p.id}.png" alt="${escapeHtml(p.name)}"><div><h3>#${String(p.id).padStart(4,'0')} ${escapeHtml(p.name)}</h3><p>${p.types.map(t=>`<span class="type-chip">${t}</span>`).join(' ')}</p><p>${state.caught.has(p.id)?'CAUGHT':'SEEN'}</p></div></div><div class="stat-list">${Object.entries(p.stats).slice(0,6).map(([k,v])=>`<span>${k.replace('-',' ').toUpperCase()}</span><b>${v}</b><i><em style="width:${Math.min(100,v/1.8)}%"></em></i>`).join('')}</div><p class="move-detail">Moves: ${(p.moves||[]).map(m=>`${typeEmoji[m.type]||'✨'} ${m.name}`).join(' · ')||'Unknown'}</p><button id="info-back" class="menu-btn">Back</button></section>`);$('#close-overlay').onclick=()=>openEncounter();$('#info-back').onclick=()=>openEncounter();}
function calcHp(id,level){return 32+Math.round((getDetail(id).stats.hp||45)*.55)+level*2;}
function openShop(){state.mode='shop';playSound('sfx/actions/shop-bell.wav',.4);drawOverlay(`<section class="overlay-card"><button class="overlay-close" id="close-overlay">×</button><h2>MARKET</h2><p>Coins: ${state.player.money} · Poké Balls: ${state.bag['Poké Ball']||0} · Produce: ${state.bag.Produce||0}</p><div class="shop-grid"><button class="menu-btn" data-buy="Poké Ball">Buy Poké Ball · 12</button><button class="menu-btn" data-buy="Potion">Buy Potion · 25</button><button class="menu-btn" data-buy="Berry">Buy Berry · 8</button><button class="menu-btn" id="sell-produce">Sell all produce · 8 each</button></div><p class="move-detail">Poké Balls, food and medicine are available here. Bring garden harvest to sell.</p></section>`);$('#close-overlay').onclick=closeOverlay;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyItem(b.dataset.buy));$('#sell-produce').onclick=()=>{const amount=state.bag.Produce||0;if(!amount)return showToast('No produce to sell.');state.bag.Produce=0;state.player.money+=amount*8;playSound('sfx/actions/sell-coins.wav');showToast(`Sold ${amount} crops for ${amount*8} coins.`);requestSave();openShop();};}
function buyItem(item){const cost={'Poké Ball':12,Potion:25,Berry:8}[item]||0;if(state.player.money<cost)return showToast('Not enough coins.');if(item==='Poké Ball'&&(state.bag[item]||0)>=10)return showToast('Poké Ball bag is full (10).');state.player.money-=cost;state.bag[item]=(state.bag[item]||0)+1;requestSave();openShop();}

function startWildBattle(){if(!state.encounter)return;const wild=state.encounter;const mine=activePokemon();state.mode='battleIntro';state.battle={enemyId:wild.id,enemyLevel:wild.level,enemyHp:calcHp(wild.id,wild.level),enemyMax:calcHp(wild.id,wild.level),playerHp:mine.hp,playerMax:mine.maxHp,energy:0,remaining:60,phase:'intro',intro:3,introReady:false,attacks:[],effects:[],cooldowns:[0,0,0],ultimateCooldown:0,guard:false,lastAI:1.1,aiMode:'approach',enemyX:665,enemyY:390,enemyWindup:0,level:mine.level,playerId:mine.id,result:'',capture:false};setMusic('music/battle.wav');playCry(mine.id);introOverlay();}
function introOverlay(){const b=state.battle,mine=getDetail(activePokemon().id),enemy=getDetail(b.enemyId);drawOverlay(`<section class="overlay-card"><h2>CHALLENGER APPROACHES</h2><div class="versus-row"><div><img src="/assets/pokemon-sprites/${mine.id}.png" alt="${mine.name}"><b>${mine.name}</b><small>HP ${b.playerHp}/${b.playerMax}</small><button class="small-btn" id="player-cry">▶ CRY</button></div><strong>VS</strong><div><img src="/assets/pokemon-sprites/${enemy.id}.png" alt="${enemy.name}"><b>${enemy.name}</b><small>HP ${b.enemyHp}/${b.enemyMax} · Lv.${b.enemyLevel}</small><button class="small-btn" id="enemy-cry">▶ CRY</button></div></div><div id="ready-count" class="ready-count">3</div><p>60 second real-time duel</p><button id="begin-fight" class="primary-btn hidden">FIGHT! <span>↗</span></button></section>`);$('#player-cry').onclick=()=>playCry(mine.id);$('#enemy-cry').onclick=()=>playCry(enemy.id);$('#begin-fight').onclick=()=>{state.mode='battle';state.battle.phase='fight';closeOverlay();};}
function battleEnd(won,timeout=false){const b=state.battle;if(!b||b.result)return;b.result=won?'VICTORY':timeout?'TIME UP':'DEFEAT';b.phase='result';playSound(won?'sfx/actions/jingle-level-up.wav':'sfx/actions/jingle-fail.wav');const fighter=activePokemon();fighter.hp=Math.max(0,Math.min(fighter.maxHp,b.playerHp));if(won){state.player.money+=20+state.zone*4;fighter.xp+=20+b.enemyLevel*2;while(fighter.xp>=fighter.level*20&&fighter.level<100){fighter.xp-=fighter.level*20;fighter.level++;fighter.maxHp+=3;fighter.hp=Math.min(fighter.maxHp,fighter.hp+5);}state.player.xp+=10;questProgress('battle');}renderParty();drawOverlay(`<section class="overlay-card"><h2>${b.result}</h2><div class="result-mon"><img src="/assets/pokemon-sprites/${b.enemyId}.png" alt="${getDetail(b.enemyId).name}"><p>${won?'+20 TRAINER XP · +COINS':'Visit a Pokémon Center to revive and heal.'}</p></div>${won&&b.enemyHp/b.enemyMax<.38?'<button id="capture-btn" class="primary-btn">THROW POKÉ BALL <span>O</span></button>':''}<button id="battle-close" class="menu-btn">Return to trail · Enter</button></section>`);$('#battle-close').onclick=leaveBattle;if($('#capture-btn'))$('#capture-btn').onclick=throwBall;requestSave();}
function leaveBattle(){state.battle=null;state.encounter=null;state.mode='game';closeOverlay();setZoneMusic();populateZone(true);requestSave();}
function throwBall(){const b=state.battle;if(!b||!state.bag['Poké Ball'])return showToast('No Poké Balls left.');playSound('sfx/actions/pickup-item.wav');state.bag['Poké Ball']--;const chance=Math.min(.88,.18+(1-b.enemyHp/b.enemyMax)*.7+(getDetail(b.enemyId).id<152?.1:0));if(Math.random()<chance){state.caught.add(b.enemyId);questProgress('catch');if(!state.team.includes(b.enemyId)){const captured=makePokemon(b.enemyId,b.enemyLevel);state.party.push(captured);state.team.push(b.enemyId);if(state.activeTeam.length<3)state.activeTeam.push(b.enemyId);}showToast(`${getDetail(b.enemyId).name} was caught!`);state.battle.result='CAUGHT';}else{showToast('The Pokémon broke free!');}requestSave();leaveBattle();}

function attack(key){const b=state.battle;if(!b||state.mode!=='battle'||b.result||b.phase!=='fight')return;const p=activePokemon();let move,distance=Math.hypot((b.playerX??300)-(b.enemyX??650),(b.playerY??390)-(b.enemyY??370));if(key==='a'){if(distance>112)return effect('MISS',300,390);move={name:'Quick Strike',type:getDetail(p.id).types[0]||'normal',power:22,emoji:'👊',range:112};}else if(key==='s')return;b.cooldowns??=[0,0,0];let index={q:0,w:1,e:2,r:3}[key];if(key==='r'){if(b.energy<100||b.ultimateCooldown>0)return;move=(getDetail(p.id).moves||[]).at(-1)||{name:'Ultimate',type:getDetail(p.id).types[0]||'normal',power:80};move={...move,power:Math.max(70,move.power*1.9),emoji:typeEmoji[move.type]||'✨',name:`Ultimate ${move.name}`,range:1000,ultimate:true};b.energy=0;b.ultimateCooldown=12;}else{if(index<0)return;if(index<3&&b.cooldowns[index]>0)return;move=(getDetail(p.id).moves||[])[index]||{name:['Stun Bloom','Close Strike','Element Shot'][index],type:getDetail(p.id).types[index%getDetail(p.id).types.length]||'normal',power:[15,38,48][index],accuracy:90,emoji:typeEmoji[getDetail(p.id).types[index%getDetail(p.id).types.length]]||'✨'};move={...move,emoji:typeEmoji[move.type]||'✨',range:index===0?500:index===1?135:680,stun:index===0,cooldown:[6,3,4][index]};if(index===0&&distance>move.range)return effect('OUT OF RANGE',300,390);b.cooldowns[index]=move.cooldown;}
 const from={x:b.playerX??300,y:b.playerY??390},to={x:b.enemyX??650,y:b.enemyY??370};const ranged=key==='e'||key==='q'||key==='r';if(!ranged&&distance>(move.range||100))return effect('MISS',from.x,from.y);playSound(key==='r'?'sfx/ultimate_charge.ogg':key==='a'?'sfx/punch.ogg':typeSfx(move.type),key==='r' ? .75 : .4);b.attacks.push({move,from,to,t:0,duration:key==='r' ? .38 : .25,key});if(key==='r'){b.cutIn=.65;playCry(p.id);} }
function effect(text,x,y){state.battle?.effects.push({text,x,y,t:0});}
function doCapture(){throwBall();}

function openPokedex(){const entries=species.map(p=>`<button class="dex-item" data-dex="${p.id}" aria-label="${p.name}, #${p.id}"><img loading="lazy" src="/assets/pokemon-sprites/${p.id}.png" alt=""><small>#${String(p.id).padStart(4,'0')}</small><b>${escapeHtml(p.name)}</b><small>${state.caught.has(p.id)?'CAUGHT':state.seen.has(p.id)?'SEEN':'UNKNOWN'}</small></button>`).join('');drawOverlay(`<section class="overlay-card dex-card"><button class="overlay-close" id="close-overlay">×</button><h2>POKÉDEX · ${state.caught.size} CAUGHT / ${state.seen.size} SEEN</h2><label for="dex-filter">Search species</label><input id="dex-filter" placeholder="Name or number" autocomplete="off"><div class="dex-grid" id="dex-grid">${entries}</div></section>`);$('#close-overlay').onclick=closeOverlay;$('#dex-filter').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.dex-item').forEach(el=>{const p=byId.get(+el.dataset.dex);el.classList.toggle('hidden',!(`${p.name} ${p.id}`.toLowerCase().includes(q)));});};document.querySelectorAll('[data-dex]').forEach(b=>b.onclick=()=>openPokemonInfo(+b.dataset.dex));state.mode='dex';}
function openBag(){drawOverlay(`<section class="overlay-card"><button class="overlay-close" id="close-overlay">×</button><h2>TRAINER BAG</h2><p>Carry up to 10 Poké Balls · caught Pokémon stay in your collection.</p><div class="bag-grid">${Object.entries(state.bag).map(([n,q])=>`<div>${n}<b>× ${q}</b></div>`).join('')}</div><div class="encounter-buttons"><button class="menu-btn" id="eat-berry">Eat Berry · +hunger</button><button class="menu-btn" id="use-potion">Use Potion · +health</button></div><p>Active team ${state.activeTeam.length}/3 · collection ${state.team.length}</p><div class="party-select">${state.team.map(id=>`<button class="menu-btn" data-team="${id}">${state.activeTeam.includes(id)?`ACTIVE ${state.activeTeam.indexOf(id)+1}`:'SET ACTIVE'} · ${escapeHtml(getDetail(id).name)} · Lv.${state.party.find(x=>x.id===id)?.level||5}</button>`).join('')}</div><button id="close2" class="menu-btn">Close</button></section>`);$('#close-overlay').onclick=closeOverlay;$('#close2').onclick=closeOverlay;$('#eat-berry').onclick=()=>useItem('Berry');$('#use-potion').onclick=()=>useItem('Potion');document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>activatePokemon(+b.dataset.team));state.mode='bag';}
function useItem(name){if((state.bag[name]||0)<1)return showToast(`No ${name} left.`);state.bag[name]--;if(name==='Berry'){state.player.full=Math.min(100,state.player.full+30);state.player.mood=Math.min(100,state.player.mood+5);playSound('sfx/actions/eat.wav');}if(name==='Potion')state.player.hp=Math.min(state.player.maxHp,state.player.hp+35);requestSave();showToast(name==='Berry'?'You enjoyed a berry.':'Potion restored your health.');openBag();}
function openMap(){const tiles=zones.map((z,i)=>`<button class="map-cell ${i===state.zone?'current':''}" data-zone="${i}"><b>${String(i+1).padStart(2,'0')}</b><span>${escapeHtml(z[0])}</span><small>${i<4?'OPEN':`AREA ${Math.floor(i/4)+1}`}</small></button>`).join('');drawOverlay(`<section class="overlay-card map-card"><button class="overlay-close" id="close-overlay">×</button><h2>WORLD MAP · 16 BIOMES</h2><p>Explore every space. Pokémon rarity rises farther from home.</p><div class="world-map">${tiles}</div></section>`);$('#close-overlay').onclick=closeOverlay;document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{const z=+b.dataset.zone;if(Math.abs(z%4-state.zone%4)+Math.abs(Math.floor(z/4)-Math.floor(state.zone/4))>1){showToast('Follow connected trails to reach that space.');return;}state.zone=z;state.player.x=600;state.player.y=440;populateZone(true);setZoneMusic();updateHud();closeOverlay();requestSave();});state.mode='map';}

function connectOnline(){if(state.online.client||state.online.connecting)return;const url=prompt('Online server HTTPS URL',state.online.url||'');if(!url)return;state.online.url=url.replace(/\/$/,'');localStorage.setItem('openrpg-online-url',state.online.url);const payload={token:state.online.token,name:state.user.username,character:state.player.style,roster:Object.fromEntries(state.team.map(id=>[id,state.party.find(p=>p.id===id)?.level||5])),active:state.activeTeam,money:state.player.money,items:state.bag};
  const poll=async body=>{const response=await fetch(state.online.url+body.path,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.online.token},body:JSON.stringify(body.payload)});const data=await response.json();if(!response.ok)throw Error(data.error||'Online server refused connection.');return data;};
  state.online.connecting=true;poll({path:'/connect',payload:{...payload,join_code:prompt('Room code (optional)','')||''}}).then(data=>{state.online.token=data.token;localStorage.setItem('openrpg-online-token',data.token);state.online.client={poll,last:0,keys:{}};state.online.poll=0;state.online.state=data;state.mode='online';drawOnline();showToast('Connected to online room.');}).catch(e=>{showToast(e.message);}).finally(()=>{state.online.connecting=false;});}
async function onlineAction(action='input',payload={}){if(!state.online.client)return;try{const hadBattle=Boolean(state.online.state?.battle),data=await state.online.client.poll({path:'/action',payload:{action,...payload}});state.online.state=data;state.online.last=performance.now();if(action==='input'){handleOnlineOffers(data);handleOnlineSounds(data);if(!hadBattle&&data.battle)setMusic('music/battle.wav');if(hadBattle&&!data.battle)setZoneMusic();}if(action==='reply'){state.online.invite=null;showToast(payload.accept?'Invitation accepted.':'Invitation declined.');}if(action==='input'&&state.mode==='online'&&state.overlay&&$('#online-title'))refreshOnlinePanel(data);}catch(e){showToast(e.message);disconnectOnline();}}
function handleOnlineSounds(data){for(const event of data.battle?.events||[]){if(event.seq<=state.online.lastEventSeq)continue;state.online.lastEventSeq=event.seq;if(event.kind==='attack'){playSound(event.ultimate?'sfx/ultimate_charge.ogg':typeSfx(event.type),event.ultimate ? .65 : .35);}if(event.kind==='hit'){playCry(event.pokemon);playSound(event.ultimate?'sfx/ultimate_explosion.ogg':'sfx/actions/hurt_01.ogg',.45);}}}
function handleOnlineOffers(data){const offer=(data.offers||[]).find(o=>o.to===data.me?.id&&!state.online.seenOffers.has(o.id));if(!offer||state.mode==='onlineOffer')return;state.online.seenOffers.add(offer.id);state.online.invite=offer;state.mode='onlineOffer';drawOverlay(`<section class="overlay-card"><h2>${offer.kind==='pvp'?'TRAINER CHALLENGE':'POKÉMON TRADE'}</h2><p><b>${escapeHtml(offer.name||'A trainer')}</b> ${offer.kind==='pvp'?'challenges you to a battle.':'offers a trade.'}</p>${offer.kind==='trade'?`<p>They offer ${escapeHtml(getDetail(offer.give).name)}${offer.want?` for your ${escapeHtml(getDetail(offer.want).name)}`:' for free'} · ${offer.price||0} coins</p>`:''}<div class="encounter-buttons"><button class="menu-btn" id="offer-decline">Decline</button><button class="menu-btn highlighted" id="offer-accept">Accept</button></div></section>`);$('#offer-decline').onclick=()=>{state.mode='online';closeOverlay();onlineAction('reply',{offer:offer.id,accept:false});};$('#offer-accept').onclick=()=>{state.mode='online';closeOverlay();onlineAction('reply',{offer:offer.id,accept:true});};}
function refreshOnlinePanel(data){const list=$('#online-roster');if(!list)return;list.innerHTML=(data.players||[]).filter(p=>p.id!==data.me?.id).map(p=>`<div><b>${escapeHtml(p.name)}</b><span>(${Math.round(p.x)}, ${Math.round(p.y)})</span><button class="small-btn" data-pvp="${escapeHtml(p.id)}">PVP</button><button class="small-btn" data-trade="${escapeHtml(p.id)}">TRADE</button></div>`).join('')||'<p>No other trainers in this room yet.</p>';document.querySelectorAll('[data-pvp]').forEach(b=>b.onclick=()=>onlineAction('pvp',{target:b.dataset.pvp}));document.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>openTradeOffer(b.dataset.trade));const chat=$('#online-chat');if(chat)chat.innerHTML=(data.chat||[]).slice(-7).map(c=>`<p><b>${escapeHtml(c.name)}:</b> ${escapeHtml(c.text)}</p>`).join('');}
function openTradeOffer(target){const choice=prompt(`Pokemon ID to offer (owned: ${state.team.join(', ')})`,String(state.team[0]||''));if(!choice||!state.team.includes(+choice))return showToast('Choose a Pokémon you own.');const price=Number(prompt('Coin price (0 for free)', '0')||0);if(!Number.isInteger(price)||price<0)return showToast('Enter a valid coin price.');onlineAction('trade',{target,give:+choice,price});showToast('Trade offer sent.');}
function disconnectOnline(){const client=state.online.client;if(client){client.poll({path:'/action',payload:{action:'disconnect'}}).catch(()=>{});}state.online.client=null;state.online.state=null;state.online.keys={};if(state.mode==='online'||state.mode==='onlineOffer')state.mode='game';setZoneMusic();}
function drawOnline(){const d=state.online.state;if(!d)return;const people=(d.players||[]).filter(p=>p.id!==d.me?.id),inDungeon=String(d.room||'').startsWith('dungeon:'),unlocked=Math.max(1,Math.min(10,d.me?.unlocked||1));drawOverlay(`<section class="overlay-card"><button class="overlay-close" id="close-overlay">×</button><h2 id="online-title">ONLINE / ${escapeHtml(d.room||'GYM')}</h2><p>${(d.players||[]).length} trainers in room · arrows move · T chat · E challenge nearby trainers.</p><div class="online-list" id="online-roster">${people.map(p=>`<div><b>${escapeHtml(p.name)}</b><span>(${Math.round(p.x)}, ${Math.round(p.y)})</span><button class="small-btn" data-pvp="${escapeHtml(p.id)}">PVP</button><button class="small-btn" data-trade="${escapeHtml(p.id)}">TRADE</button></div>`).join('')||'<p>No other trainers in this room yet.</p>'}</div><div class="online-chat" id="online-chat">${(d.chat||[]).slice(-7).map(c=>`<p><b>${escapeHtml(c.name)}:</b> ${escapeHtml(c.text)}</p>`).join('')}</div>${inDungeon?'<p>Dungeon lobby: ready up together, then start a raid.</p><div class="encounter-buttons"><button class="menu-btn" id="ready-raid">Ready / Unready</button><button class="menu-btn highlighted" id="start-raid">Start raid</button></div>':`<p>Unlocked dungeons · ${unlocked} / 10</p><div class="dungeon-choices">${Array.from({length:10},(_,i)=>`<button class="small-btn" data-dungeon="${i+1}" ${i+1>unlocked?'disabled':''}>${String(i+1).padStart(2,'0')} · ${i+1>unlocked?'LOCKED':'ENTER'}</button>`).join('')}</div><button class="menu-btn" id="gym-room">Return to online gym</button>`}<button class="menu-btn" id="chat">Send chat</button><p class="move-detail">Enter accepts a finished battle · Esc leaves the online server.</p></section>`);$('#close-overlay').onclick=()=>{$('#overlay').classList.add('hidden');$('#overlay').innerHTML='';state.overlay=null;state.mode='online';};document.querySelectorAll('[data-pvp]').forEach(b=>b.onclick=()=>onlineAction('pvp',{target:b.dataset.pvp}));document.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>openTradeOffer(b.dataset.trade));document.querySelectorAll('[data-dungeon]').forEach(b=>b.onclick=()=>onlineAction('room',{room:`dungeon:${b.dataset.dungeon}`}));if($('#ready-raid'))$('#ready-raid').onclick=()=>onlineAction('ready');if($('#start-raid'))$('#start-raid').onclick=()=>onlineAction('raid');if($('#gym-room'))$('#gym-room').onclick=()=>onlineAction('room',{room:'gym'});$('#chat').onclick=()=>{const text=prompt('Chat message');if(text)onlineAction('chat',{text});};state.mode='online';}

function nearGate(){const x=state.player.x,y=state.player.y;for(const [cond,delta,from] of [[x<52,[-1,0],'right'],[x>ZW-52,[1,0],'left'],[y<52,[0,-1],'bottom'],[y>ZH-52,[0,1],'top']])if(cond){const nx=state.zone%4+delta[0],ny=Math.floor(state.zone/4)+delta[1];if(nx>=0&&nx<4&&ny>=0&&ny<4)return {index:ny*4+nx,from};}return null;}
function renderParty(){const row=$('#party-row');row.innerHTML=state.activeTeam.map((id,i)=>{const p=state.party.find(x=>x.id===id)||makePokemon(id,5);return `<div class="party-slot ${i===state.active?'active':''}"><img loading="lazy" src="/assets/pokemon-sprites/${p.id}.png" alt=""><small>${escapeHtml(getDetail(p.id).name)} Lv.${p.level}</small></div>`;}).join('')||'<div class="party-slot"><small>Choose your starter</small></div>';}
function updateHud(){const p=state.player,z=zones[state.zone],hour=Math.floor(p.hour);$('#zone-name').textContent=z[0];$('#zone-desc').textContent=z[3];$('#zone-count').textContent=`BIOME ${String(state.zone+1).padStart(2,'0')} / 16`;$('#hp-meter').style.width=`${p.hp/p.maxHp*100}%`;$('#hp-label').textContent=Math.round(p.hp);$('#coins-label').textContent=p.money;$('#clock-label').textContent=`DAY ${String(p.day).padStart(2,'0')} · ${String(hour).padStart(2,'0')}:00`;$('#weather-label').textContent=`${['CLEAR','CLOUDY','RAIN','SNOW'][Math.floor((performance.now()/140000+state.zone)%4)]} · ${hour<6||hour>19?'NIGHT':hour<11?'MORNING':hour<17?'DAY':'EVENING'}`;$('#quest-label').textContent=state.quest.name;$('#quest-progress').textContent=`${Math.min(state.quest.done,state.quest.target)} / ${state.quest.target}`;$('#quest-claim').classList.toggle('hidden',state.quest.done<state.quest.target||state.quest.claimed);$('#quest-claim').disabled=state.quest.claimed;}
function movePlayer(dt){const p=state.player;if(state.mode==='battle')return;if(state.mode==='online'||state.mode!=='game'||state.overlay)return;let dx=(state.keys.has('ArrowRight')||state.keys.has('d')?1:0)-(state.keys.has('ArrowLeft')||state.keys.has('a')?1:0),dy=(state.keys.has('ArrowDown')||state.keys.has('s')?1:0)-(state.keys.has('ArrowUp')||state.keys.has('w')?1:0);if(dx&&dy){dx*=.707;dy*=.707;}const speed=p.energy<10?90:185;p.x+=dx*speed*dt;p.y+=dy*speed*dt;p.x=Math.max(20,Math.min(ZW-20,p.x));p.y=Math.max(20,Math.min(ZH-20,p.y));if(dx||dy){p.full=Math.max(0,p.full-dt*.08);p.thirst=Math.max(0,p.thirst-dt*.11);p.energy=Math.max(0,p.energy-dt*.045);}}
function moveBattle(dt){const b=state.battle;if(!b||b.phase!=='fight'||b.result)return;const p=state.player;let dx=(state.keys.has('ArrowRight')?1:0)-(state.keys.has('ArrowLeft')?1:0),dy=(state.keys.has('ArrowDown')?1:0)-(state.keys.has('ArrowUp')?1:0);const char=b.playerX??280; b.playerX=Math.max(80,Math.min(880,char+dx*230*dt));b.playerY=Math.max(190,Math.min(470,(b.playerY??390)+dy*190*dt));b.guard=state.keys.has('s');b.remaining-=dt;b.energy=Math.min(100,b.energy+dt*5);b.cooldowns=b.cooldowns.map(x=>Math.max(0,x-dt));b.ultimateCooldown=Math.max(0,b.ultimateCooldown-dt);if(b.remaining<=0){battleEnd(b.playerHp>=b.enemyHp,true);return;}
  // The wild fighter makes visible decisions: it closes distance, pauses to telegraph,
  // attacks with a short-range lunge, then backs off before choosing its next move.
  const gap=Math.hypot(b.playerX-b.enemyX,b.playerY-b.enemyY),dxToPlayer=b.playerX-b.enemyX,dyToPlayer=b.playerY-b.enemyY;
  if(b.enemyStun<=0){if(b.enemyWindup>0){b.enemyWindup-=dt;if(b.enemyWindup<=0){if(gap<132){const dmg=6+Math.floor(b.enemyLevel*.32),blocked=b.guard&&Math.random()<.78;if(!blocked){b.playerHp=Math.max(0,b.playerHp-dmg);activePokemon().hp=Math.max(0,b.playerHp);playCry(activePokemon().id);b.effects.push({text:'💥',x:b.playerX,y:b.playerY-32,t:0});effect(`-${dmg} HP`,b.playerX,b.playerY-52);}else effect('BLOCK!',b.playerX,b.playerY-30);}else effect('WHIFF',b.enemyX,b.enemyY-30);b.aiMode='retreat';b.lastAI=.48+Math.random()*.38;}}
    else if(b.aiMode==='approach'&&gap>104){const len=Math.max(1,gap);b.enemyX+=dxToPlayer/len*112*dt;b.enemyY+=dyToPlayer/len*90*dt;}
    else if(b.aiMode==='approach'){b.aiMode='windup';b.enemyWindup=.42+Math.random()*.24;b.effects.push({text:'…',x:b.enemyX,y:b.enemyY-100,t:0});}
    else if(b.aiMode==='retreat'){if(b.lastAI>0){const len=Math.max(1,gap);b.enemyX-=dxToPlayer/len*70*dt;b.enemyY-=dyToPlayer/len*45*dt;b.lastAI-=dt;}else{b.aiMode='approach';b.lastAI=.25+Math.random()*.4;}}
  }else{b.enemyStun=Math.max(0,b.enemyStun-dt);}
  for(const shot of b.attacks){shot.t+=dt;const f=shot.t/shot.duration;if(f>=1){const hit=keyRangeHit(shot);if(hit){const move=shot.move;let dmg=Math.floor((move.power||30)*(.32+b.level*.012));if(shot.key==='r')dmg=Math.floor(dmg*1.8);const miss=Math.random()>(move.accuracy??90)/100;if(miss){effect('MISS',b.enemyX,b.enemyY);}else{b.enemyHp=Math.max(0,b.enemyHp-(b.guard?Math.ceil(dmg*.4):dmg));b.energy=Math.min(100,b.energy+(shot.key==='r'?0:15));b.effects.push({text:move.emoji||'💥',x:b.enemyX,y:b.enemyY,t:0});playCry(b.enemyId);if(shot.key==='q'&&Math.random()<.42)b.enemyStun=1+Math.random()*2;if(shot.key==='r'){b.effects.push({text:'💥',x:b.enemyX,y:b.enemyY,t:0,boom:true});}if(b.enemyHp<=0){battleEnd(true);return;}}}else effect('MISS',b.enemyX,b.enemyY);shot.t=-99;} }
  b.attacks=b.attacks.filter(s=>s.t>=0);b.effects=b.effects.filter(e=>{e.t+=dt;return e.t<.8;});b.cutIn=Math.max(0,(b.cutIn||0)-dt);b.enemyStun=Math.max(0,(b.enemyStun||0)-dt);if(b.playerHp<=0)battleEnd(false);}
function keyRangeHit(shot){const b=state.battle,d=Math.hypot(b.playerX-b.enemyX,b.playerY-b.enemyY);if(shot.key==='a')return d<105;if(shot.key==='w')return d<145;if(shot.key==='q')return d<500;if(shot.key==='e')return d<680;return true;}

function loop(time){if(!state.user)return;const dt=Math.min(.05,(time-(state.lastTime||time))/1000);state.lastTime=time;state.frame+=dt*60;if(state.mode==='battleIntro'&&state.battle){if(state.battle.intro>0)state.battle.intro-=dt;if(state.battle.intro<=0&&!state.battle.introReady){state.battle.introReady=true;$('#ready-count').textContent='FIGHT!';$('#begin-fight').classList.remove('hidden');setTimeout(()=>{if(state.mode==='battleIntro'){state.mode='battle';state.battle.phase='fight';closeOverlay();}},450);}else if(state.battle.intro>0)$('#ready-count').textContent=Math.ceil(state.battle.intro);}
 if(state.online.client){state.online.poll-=dt;if(state.online.poll<=0&&!state.online.inputBusy){const moving=Object.values(state.online.keys).some(Boolean);state.online.poll=moving ? .12 : 1.2;state.online.inputBusy=true;onlineAction('input',{keys:{...state.online.keys}}).finally(()=>state.online.inputBusy=false);}}
 movePlayer(dt);if(state.mode==='game'){for(const w of state.wild){w.timer-=dt;if(w.timer<=0){w.timer=2+Math.random()*4;w.vx=(Math.random()-.5)*55;w.vy=(Math.random()-.5)*38;if(Math.random()<.13)w.state=Math.random()<.5?'hide':'flee';else w.state='roam';}if(w.state==='hide'&&Math.random()<dt*.16)w.state='roam';if(w.state==='flee'){const dx=w.x-state.player.x,dy=w.y-state.player.y,l=Math.max(1,Math.hypot(dx,dy));w.x+=dx/l*100*dt;w.y+=dy/l*75*dt;}else if(w.state==='roam'){w.x+=w.vx*dt;w.y+=w.vy*dt;}w.x=Math.max(55,Math.min(ZW-55,w.x));w.y=Math.max(100,Math.min(ZH-55,w.y));}}
 if(state.mode==='battle')moveBattle(dt);advanceClock(dt*.009);if(state.player.full===0||state.player.thirst===0){state.player.hp=Math.max(0,state.player.hp-dt*.25);if(state.player.hp<=0){state.player.x=140;state.player.y=135;state.player.zone=0;state.zone=0;state.player.hp=state.player.maxHp;state.player.energy=100;state.player.full=100;state.player.thirst=100;state.party.forEach(p=>p.hp=Math.max(1,p.maxHp));state.mode='game';state.battle=null;state.encounter=null;closeOverlay();showToast('You fainted. You woke up safely in your bed.');requestSave();}}if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('#world-toast').classList.add('hidden');}state.saveTimer+=dt;if(state.saveTimer>10){state.saveTimer=0;saveNow();}updateHud();draw();requestAnimationFrame(loop);}

function draw(){const b=state.battle;if(state.mode==='battle'||state.mode==='battleIntro'){drawBattle(b);return;}if(state.mode==='online'){drawWorld();drawOnlineScene();return;}drawWorld();}
function drawWorld(){const [name,biome,bg]=zones[state.zone];ctx.imageSmoothingEnabled=false;ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);const camX=Math.max(0,Math.min(ZW-960,state.player.x-480)),camY=Math.max(0,Math.min(ZH-540,state.player.y-270));
  // Biome terrain: pixel grid is seeded by world coordinates so it does not shimmer while walking.
  for(let gy=Math.floor(camY/TILE)*TILE;gy<camY+540;gy+=TILE)for(let gx=Math.floor(camX/TILE)*TILE;gx<camX+960;gx+=TILE){const seed=((gx*73856093)^(gy*19349663)^(state.zone*83492791))>>>0;const n=seed%13;if(n<4){ctx.fillStyle=n===0?'#ffffff18':'#10182918';ctx.fillRect(gx-camX+(seed%34),gy-camY+((seed>>>8)%34),3+(seed%5),2+(seed%3));}}
  // Winding walking path.
  ctx.fillStyle='#bd9055';ctx.fillRect(0,400-camY,ZW,82);ctx.fillRect(535-camX,0,90,ZH);ctx.fillStyle='#d9b66c';ctx.fillRect(0,400-camY,ZW,4);ctx.fillRect(535-camX,0,4,ZH);
  drawDecor(camX,camY);
  // Home cabin, market and Pokémon center make the first clearing immediately useful.
  if(state.zone===0){drawBuilding(90-camX,95-camY,'HOME','#a84455');drawBuilding(1010-camX,95-camY,'MARKET','#c57a48');drawBuilding(1010-camX,710-camY,'CENTER','#447aa0');drawGarden(105-camX,650-camY);}
  for(const w of state.wild){const x=w.x-camX,y=w.y-camY;if(x<-80||x>1040||y<-90||y>630)continue;const p=getDetail(w.id);if(w.state==='hide'){if(Math.floor(state.frame/15)%2)continue;ctx.fillStyle='#b4d777';ctx.fillRect(x-3,y-5,6,6);continue;}const im=sprite(w.id);if(im.complete&&im.naturalWidth){const size=w.rare?66:48,bob=Math.sin(state.frame/12+w.id)*2;ctx.drawImage(im,x-size/2,y-size+bob,size,size);if(w.rare){ctx.fillStyle='#ffd56d';ctx.fillRect(x-2,y-size-10,4,4);}}else{ctx.fillStyle=colors[p.types[0]]||'#e8dfb7';ctx.fillRect(x-12,y-17,24,20);}if(w.state==='flee'&&Math.floor(state.frame/9)%2===0){ctx.font='20px serif';ctx.fillText('💨',x,y-43);}if(Math.hypot(w.x-state.player.x,w.y-state.player.y)<110){drawNameTag(x,y+4,`${p.name} · Lv.${w.level}${w.rare?' ★':''}`);}}
  const px=state.player.x-camX,py=state.player.y-camY;drawTrainer(px,py,state.frame);const gate=nearGate();if(gate){ctx.fillStyle='#ffe090';ctx.font='16px "Press Start 2P"';ctx.fillText('E  TRAIL →',Math.max(15,Math.min(820,px-52)),Math.max(42,Math.min(510,py-25)));}
  const nearby=nearestPokemon(95);if(nearby)drawNameTag(480,492,`E  ${getDetail(nearby.id).name}  ·  meet`);
  if(state.player.full<35||state.player.thirst<35)drawNameTag(480,42,`LOW NEEDS · Eat or drink at home/market`);
}
function drawDecor(cx,cy){const idx=state.zone;for(let i=0;i<13;i++){const x=((i*191+idx*89)%1160)+20-cx,y=((i*127+idx*103)%820)+45-cy;if(x<-100||x>1050||y<-100||y>650)continue;ctx.fillStyle=idx%4===0?'#214c37':'#375d38';ctx.fillRect(x-21,y-8,42,30);ctx.fillStyle=idx%4===0?'#548d45':'#72964b';ctx.fillRect(x-25,y-31,50,25);ctx.fillRect(x-18,y-39,36,10);ctx.fillStyle='#8c573c';ctx.fillRect(x-5,y+14,10,8);}}
function drawBuilding(x,y,label,roof){ctx.fillStyle='#1b263b';ctx.fillRect(x+3,y+5,96,76);ctx.fillStyle='#dfd0ac';ctx.fillRect(x,y+16,92,62);ctx.fillStyle=roof;ctx.fillRect(x-5,y+6,102,15);ctx.fillRect(x+8,y-6,76,15);ctx.fillStyle='#624554';ctx.fillRect(x+36,y+42,21,36);ctx.fillStyle='#93cbe0';ctx.fillRect(x+9,y+30,18,18);ctx.fillRect(x+66,y+30,18,18);ctx.fillStyle='#0c1429';ctx.font='10px "Press Start 2P"';ctx.fillText(label,x+4,y-14);}
function drawGarden(x,y){ctx.fillStyle='#70513c';for(let i=0;i<4;i++){ctx.fillRect(x+i*35,y,25,17);const crop=state.farm[i],ready=crop&&worldMinutes()>=crop.readyAt;ctx.fillStyle=ready?'#f3bc58':crop?'#75bd5a':'#a97848';ctx.fillRect(x+8+i*35,y-(crop?10:5),9,crop?12:7);if(ready){ctx.fillStyle='#ffe18a';ctx.fillRect(x+5+i*35,y-18,15,4);}}}
function drawNameTag(x,y,text){ctx.font='11px "Press Start 2P"';const w=ctx.measureText(text).width+18;ctx.fillStyle='#0c1429';ctx.fillRect(x-w/2,y-14,w,24);ctx.fillStyle='#fff1cf';ctx.fillText(text,x-w/2+9,y+3);}
function drawTrainer(x,y,t){const bob=Math.sin(t/8)*2;ctx.fillStyle='#182038';ctx.fillRect(x-11,y-22+bob,22,25);ctx.fillStyle=state.player.gender==='female'?'#d86d63':'#538bc5';ctx.fillRect(x-9,y-20+bob,18,17);ctx.fillStyle='#e4b783';ctx.fillRect(x-7,y-34+bob,14,13);ctx.fillStyle='#9f5f44';ctx.fillRect(x-10,y-36+bob,20,6);ctx.fillStyle='#273452';ctx.fillRect(x-8,y+2,6,8);ctx.fillRect(x+2,y+2,6,8);}
function drawBattle(b){if(!b)return;const p=getDetail(activePokemon().id),e=getDetail(b.enemyId);const isWater=zones[state.zone][1]==='water',bg=isWater?'#3185a2':zones[state.zone][2];ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);ctx.fillStyle='#f5d681';ctx.beginPath();ctx.arc(810,105,44,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){ctx.fillStyle=`hsl(${130+i*7} 25% ${30+i*3}%)`;ctx.beginPath();ctx.ellipse(i*235+70,260,130,60,0,Math.PI,Math.PI*2);ctx.fill();}ctx.fillStyle='#d4bf8b';ctx.fillRect(0,357,960,143);ctx.fillStyle='#9b835a';ctx.beginPath();ctx.ellipse(480,420,360,38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7d6247';ctx.fillRect(0,500,960,40);
 drawFighterCard(24,20,320,p.name,b.playerHp,b.playerMax,true,b.energy);drawFighterCard(616,20,320,e.name,b.enemyHp,b.enemyMax,false,0);const playerSprite=sprite(activePokemon().id),enemySprite=sprite(b.enemyId);const px=b.playerX??300,py=b.playerY??390,ex=b.enemyX??665,ey=b.enemyY??390;
 if(playerSprite.complete&&playerSprite.naturalWidth){ctx.save();ctx.translate(px,py);ctx.scale(-1,1);ctx.drawImage(playerSprite,-46,-86,92,92);ctx.restore();}else drawTrainer(px,py,state.frame);
 if(enemySprite.complete&&enemySprite.naturalWidth)ctx.drawImage(enemySprite,ex-46,ey-86,92,92);
 if(b.guard){ctx.strokeStyle='#6ac4f0';ctx.lineWidth=4;ctx.beginPath();ctx.arc(px,py-30,54,0,Math.PI*2);ctx.stroke();}
 for(const s of b.attacks){if(s.t<0)continue;const f=Math.min(1,s.t/s.duration),x=s.from.x+(s.to.x-s.from.x)*f,y=s.from.y+(s.to.y-s.from.y)*f;ctx.font=`${s.key==='r'?58:28}px serif`;ctx.textAlign='center';ctx.fillText(s.move.emoji||'💥',x,y);if(s.key==='r'){ctx.strokeStyle=colors[s.move.type]||'#fff';ctx.lineWidth=18;ctx.beginPath();ctx.moveTo(s.from.x,s.from.y);ctx.lineTo(x,y);ctx.stroke();}}
 for(const ef of b.effects){ctx.globalAlpha=Math.max(0,1-ef.t);ctx.font=`${ef.boom?60:23}px serif`;ctx.textAlign='center';ctx.fillText(ef.text,ef.x,ef.y-ef.t*22);ctx.globalAlpha=1;}
 if(b.cutIn>0){ctx.fillStyle='#0b1228dd';ctx.fillRect(0,0,960,540);ctx.fillStyle=colors[getDetail(activePokemon().id).types[0]]||'#ffcd68';ctx.beginPath();ctx.moveTo(0,110);ctx.lineTo(960,30);ctx.lineTo(960,420);ctx.lineTo(0,500);ctx.fill();ctx.fillStyle='#111b34';ctx.beginPath();ctx.moveTo(0,140);ctx.lineTo(960,70);ctx.lineTo(960,380);ctx.lineTo(0,460);ctx.fill();if(playerSprite.complete)ctx.drawImage(playerSprite,180,220,240,240);ctx.fillStyle='#ffcd68';ctx.font='22px "Press Start 2P"';ctx.textAlign='center';ctx.fillText('ULTIMATE!',690,174);ctx.font='62px serif';ctx.fillText(typeEmoji[p.types[0]]||'✨',700,295);}
 ctx.textAlign='left';ctx.fillStyle='#0c1429';ctx.fillRect(0,500,960,40);ctx.fillStyle='#e8f0d0';ctx.font='14px "Press Start 2P"';ctx.fillText('A HIT · S GUARD · Q STUN · W CLOSE · E RANGED · R ULT · 1-3 TEAM',20,525);ctx.fillStyle='#ffcd68';ctx.fillRect(420,117,120,37);ctx.fillStyle='#111b34';ctx.font='18px "Press Start 2P"';ctx.textAlign='center';ctx.fillText(`${Math.max(0,Math.ceil(b.remaining))}`,480,143);ctx.textAlign='left';
 if(state.mode==='battleIntro'){ctx.fillStyle='#08101fdc';ctx.fillRect(0,0,960,540);ctx.fillStyle='#ffcd68';ctx.font='25px "Press Start 2P"';ctx.textAlign='center';ctx.fillText('CHALLENGER APPROACHES',480,245);ctx.font='40px "Press Start 2P"';ctx.fillText(String(Math.max(1,Math.ceil(b.intro))),480,310);ctx.textAlign='left';}}
function drawFighterCard(x,y,w,name,hp,max,player,energy){ctx.fillStyle='#17233d';ctx.fillRect(x,y,w,76);ctx.fillStyle='#fff1cf';ctx.font='17px "Press Start 2P"';ctx.fillText(name,x+15,y+25);ctx.fillStyle='#364353';ctx.fillRect(x+15,y+39,w-30,14);ctx.fillStyle=hp/max>.35?'#72d48a':'#ff7975';ctx.fillRect(x+15,y+39,(w-30)*Math.max(0,hp/max),14);ctx.fillStyle='#c5d0de';ctx.font='16px VT323';ctx.fillText(`HP ${Math.ceil(hp)} / ${max}`,x+15,y+69);if(player){ctx.fillStyle='#39485b';ctx.fillRect(x+15,y+80,w-30,7);ctx.fillStyle='#ffcd68';ctx.fillRect(x+15,y+80,(w-30)*energy/100,7);ctx.fillStyle='#ffcd68';ctx.font='14px VT323';ctx.fillText(`ULTIMATE ${Math.floor(energy)}%`,x+15,y+102);}}

function drawOnlineScene(){const d=state.online.state;if(!d)return;if(d.battle){drawOnlineBattle(d);return;}ctx.fillStyle='#0d172d';ctx.fillRect(0,0,960,540);ctx.fillStyle='#427248';ctx.fillRect(0,110,960,430);ctx.fillStyle='#aa824e';ctx.fillRect(0,300,960,90);ctx.fillStyle='#ffcd68';ctx.font='15px "Press Start 2P"';ctx.fillText(`${String(d.room||'GYM').toUpperCase()} · ONLINE`,22,38);for(const pl of d.players||[]){const x=45+(pl.x%870),y=145+(pl.y%320);ctx.fillStyle='#d87b69';ctx.fillRect(x-10,y-25,20,28);drawNameTag(x,y-31,pl.name);}ctx.fillStyle='#fff1cf';ctx.font='15px VT323';ctx.fillText('ARROWS MOVE · E INVITE NEAREST · T CHAT · O ROOM MENU · ESC LEAVE',20,520);}
function drawOnlineBattle(d){const battle=d.battle;ctx.fillStyle='#286f8d';ctx.fillRect(0,0,960,540);ctx.fillStyle='#d0ba85';ctx.fillRect(0,360,960,140);ctx.fillStyle='#9b835a';ctx.beginPath();ctx.ellipse(480,425,360,38,0,0,Math.PI*2);ctx.fill();const ownId=d.me?.id,own=battle.fighters?.[ownId];drawFighterCard(24,20,320,own?.team?.[own.slot]?.name||'Your Pokémon',own?.team?.[own.slot]?.hp||0,own?.team?.[own.slot]?.maximum||1,true,own?.energy||0);const enemy=Object.values(battle.fighters||{}).find(f=>f.side!==(own?.side||0));if(enemy)drawFighterCard(616,20,320,enemy.team[enemy.slot].name,enemy.team[enemy.slot].hp,enemy.team[enemy.slot].maximum,false,0);for(const [uid,f]of Object.entries(battle.fighters||{})){const creature=f.team[f.slot],im=sprite(creature.id),x=uid===ownId?f.x:960-f.x,y=f.y;if(im.complete&&im.naturalWidth)ctx.drawImage(im,x-48,y-105,96,96);else drawTrainer(x,y,0);}for(const shot of battle.shots||[]){ctx.font=shot.ultimate?'50px serif':'25px serif';ctx.textAlign='center';ctx.fillText(shot.emoji||'💥',shot.x,shot.y);}for(const effect of battle.effects||[]){if(effect.blast){ctx.strokeStyle=colors[effect.type]||'#ffcd68';ctx.beginPath();ctx.arc(effect.x,effect.y,30+(1-effect.ttl/.7)*70,0,Math.PI*2);ctx.stroke();}ctx.font='28px serif';ctx.textAlign='center';ctx.fillText(effect.text||'💥',effect.x,effect.y);}ctx.textAlign='center';ctx.fillStyle='#ffcd68';ctx.font='20px "Press Start 2P"';ctx.fillText(`${Math.ceil(battle.remaining)}s`,480,150);ctx.fillStyle='#fff1cf';ctx.font='13px "Press Start 2P"';ctx.fillText('A HIT · S GUARD · Q STUN · W CLOSE · E RANGE · R ULTIMATE · 1-3 TEAM',480,525);if(battle.result){ctx.font='28px "Press Start 2P"';ctx.fillStyle='#ffcd68';ctx.fillText(battle.result.winner===own?.side?'VICTORY':'DEFEAT',480,285);}ctx.textAlign='left';}

function renderGameText(){return JSON.stringify({coordinateSystem:'origin top-left; x right, y down',mode:state.mode,zone:zones[state.zone][0],player:{x:Math.round(state.player.x),y:Math.round(state.player.y),hp:Math.round(state.player.hp),energy:Math.round(state.player.energy)},nearby:state.wild.filter(w=>Math.hypot(w.x-state.player.x,w.y-state.player.y)<180).map(w=>({id:w.id,name:getDetail(w.id).name,x:Math.round(w.x),y:Math.round(w.y),level:w.level,state:w.state})),activeTeam:state.activeTeam.map((id,i)=>{const p=state.party.find(x=>x.id===id)||makePokemon(id,5);return {slot:i+1,name:getDetail(id).name,level:p.level,hp:p.hp,maxHp:p.maxHp};}),collection:state.team.length,coins:state.player.money,bag:state.bag,battle:state.battle?{enemy:getDetail(state.battle.enemyId).name,enemyPosition:{x:Math.round(state.battle.enemyX),y:Math.round(state.battle.enemyY)},playerHp:Math.ceil(state.battle.playerHp),hp:state.battle.enemyHp,time:Math.ceil(state.battle.remaining),ultimate:state.battle.energy}:null});}
window.render_game_to_text=renderGameText;window.advanceTime=ms=>{const frames=Math.max(1,Math.round(ms/(1000/60)));for(let i=0;i<frames;i++){const dt=1/60;state.frame+=1;movePlayer(dt);if(state.mode==='battle')moveBattle(dt);}updateHud();draw();};

$('#dex-btn').onclick=openPokedex;$('#bag-btn').onclick=openBag;$('#map-btn').onclick=openMap;$('#online-btn').onclick=connectOnline;$('#quest-claim').onclick=claimQuest;$('#fullscreen-btn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.querySelector('.game-stage').requestFullscreen?.();
function setOnlineKey(key,value){const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'a',s:'guard',q:'q',w:'w',e:'e',r:'r','1':'1','2':'2','3':'3'};if(map[key])state.online.keys[map[key]]=value;}
window.addEventListener('keydown',e=>{if(currentMusic?.paused)currentMusic.play().catch(()=>{});if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const k=e.key.toLowerCase();if(e.target.matches('input,textarea'))return;if(state.overlay){if(k==='escape'){if(state.mode==='battleIntro')leaveBattle();else if(state.mode==='online'){$('#overlay').classList.add('hidden');state.overlay=null;state.mode='online';}else closeOverlay();}if(k==='enter'&&$('#battle-close'))leaveBattle();return;}state.keys.add(e.key);if(state.mode==='online'){if(k==='enter'&&state.online.state?.battle?.result){onlineAction('leave_battle');return;}if(e.key.startsWith('Arrow')||['a','s','q','w','e','r','1','2','3'].includes(k)){setOnlineKey(e.key.startsWith('Arrow')?e.key:k,true);if(k==='e'&&!state.online.state?.battle){const d=state.online.state,me=d?.players?.find(x=>x.id===d.me?.id);const target=d?.players?.filter(x=>x.id!==d.me?.id).sort((x,y)=>Math.hypot(x.x-(me?.x||0),x.y-(me?.y||0))-Math.hypot(y.x-(me?.x||0),y.y-(me?.y||0)))[0];if(target)onlineAction('pvp',{target:target.id});}}else if(k==='o')drawOnline();else if(k==='escape')disconnectOnline();else if(k==='t'){const text=prompt('Chat message');if(text)onlineAction('chat',{text});}return;}if(state.mode==='battle'){if(['a','q','w','e','r'].includes(k))attack(k);if(k>='1'&&k<='3'&&+k<=state.activeTeam.length){state.active=+k-1;const fighter=activePokemon();state.battle.playerHp=fighter.hp;state.battle.playerMax=fighter.maxHp;renderParty();}return;}if(k==='e')interact();else if(k==='p')openPokedex();else if(k==='i')openBag();else if(k==='m')openMap();else if(k==='o')connectOnline();else if(k==='t'){advanceClock(1);updateHud();requestSave();showToast('Time advanced by one in-game hour.');}});
window.addEventListener('keyup',e=>{state.keys.delete(e.key);if(state.mode==='online')setOnlineKey(e.key.startsWith('Arrow')?e.key:e.key.toLowerCase(),false);});window.addEventListener('blur',()=>{state.keys.clear();state.online.keys={};});window.addEventListener('beforeunload',()=>{saveNow();disconnectOnline();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveNow();});

async function boot(){try{const data=await api('/api/auth/me');applyUser(data.user);}catch{setTab('register');}if(!species.length)showToast('Pokédex data failed to load. Refresh to retry.');}
boot();
